import pandas as pd

# Define source file paths
source_files = [
    "autopipeline-benchmarks/github-pipelines/length4_43/test_0.csv",
    "autopipeline-benchmarks/github-pipelines/length4_43/test_1.csv",
    "autopipeline-benchmarks/github-pipelines/length4_43/test_2.csv",
    "autopipeline-benchmarks/github-pipelines/length4_43/test_3.csv"
]

# Function to clean and convert company to string
def company_to_str(company):
    if pd.isna(company):
        return ""
    return str(company).strip()

# Function to convert org_salary_period to int code
def org_salary_period_to_int(period):
    if pd.isna(period):
        return 0
    period = str(period).strip().lower()
    mapping = {
        'year': 1,
        'month': 2,
        'day': 3,
        'hour': 4
    }
    return mapping.get(period, 0)

# Function to convert rate to int
def rate_to_int(rate):
    if pd.isna(rate):
        return 0
    try:
        return int(round(float(str(rate).replace(',', ''))))
    except:
        return 0

# Function to convert reviews to int
def reviews_to_int(reviews):
    if pd.isna(reviews):
        return 0
    try:
        return int(str(reviews).replace(',', '').strip())
    except:
        return 0

# Function to convert salary to int
def salary_to_int(salary):
    if pd.isna(salary):
        return 0
    try:
        return int(round(float(str(salary).replace(',', '').strip())))
    except:
        return 0

# Load all source dataframes
dfs = []
for file in source_files:
    df = pd.read_csv(file, index_col=0)
    dfs.append(df)

# Concatenate all dataframes (UNION)
df_all = pd.concat(dfs, ignore_index=True)

# Clean company column
df_all['company'] = df_all['company'].apply(company_to_str)

# Build mappings for categorical columns to integer codes
def build_mapping(series):
    unique_vals = series.dropna().unique()
    mapping = {val: idx+1 for idx, val in enumerate(sorted(unique_vals))}
    return mapping

title_map = build_mapping(df_all['title'])
location_map = build_mapping(df_all['location'])
summary_map = build_mapping(df_all['summary'])
href_map = build_mapping(df_all['href'])

# Map categorical columns
df_all['title'] = df_all['title'].map(title_map).fillna(0).astype(int)
df_all['location'] = df_all['location'].map(location_map).fillna(0).astype(int)
df_all['summary'] = df_all['summary'].map(summary_map).fillna(0).astype(int)
df_all['href'] = df_all['href'].map(href_map).fillna(0).astype(int)

# Map org_salary_period using fixed mapping
df_all['org_salary_period'] = df_all['org_salary_period'].apply(org_salary_period_to_int).astype(int)

# Convert numeric columns
df_all['salary'] = df_all['salary'].apply(salary_to_int)
df_all['rate'] = df_all['rate'].apply(rate_to_int)
df_all['reviews'] = df_all['reviews'].apply(reviews_to_int)

# Group by 'company' (primary key) and aggregate other columns by min
agg_dict = {
    'title': 'min',
    'location': 'min',
    'summary': 'min',
    'salary': 'min',
    'href': 'min',
    'rate': 'min',
    'reviews': 'min',
    'org_salary_period': 'min'
}

df_grouped = df_all.groupby('company', as_index=False).agg(agg_dict)

# Reorder columns to target schema order
target_columns = ['company', 'title', 'location', 'summary', 'salary', 'href', 'rate', 'reviews', 'org_salary_period']
df_target = df_grouped[target_columns]

# Save to CSV
output_path = "autopipeline-benchmarks/github-pipelines/length4_43/target_multisource_critique_history.csv"
df_target.to_csv(output_path, index=False)
